import pandas as pd

def clean(df: pd.DataFrame) -> pd.DataFrame:
    # 1. Drop exact duplicate rows
    df = df.drop_duplicates().reset_index(drop=True)
    # 2. Standardize Category values (strip surrounding whitespace)
    if 'Category' in df.columns:
        df['Category'] = df['Category'].astype(str).str.strip()
    # 3. Clean Price column: remove currency symbols, commas, whitespace and convert to numeric
    if 'Price' in df.columns:
        df['Price'] = df['Price'].astype(str).str.replace(r'[^0-9\.]+', '', regex=True)
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    # 4. Ensure Quantity is numeric
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
        # 5. Remove rows with non‑positive Quantity (negative or zero) as they are invalid
        df = df[df['Quantity'] > 0]
    # 6. Re‑calculate Revenue to guarantee consistency (optional but useful)
    if {'Quantity', 'Price'}.issubset(df.columns):
        df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df: pd.DataFrame) -> dict:
    # Assume df is already cleaned via clean()
    # Group by Region and sum the units sold (Quantity)
    if 'Region' not in df.columns or 'Quantity' not in df.columns:
        return {}
    result_series = df.groupby('Region', dropna=False)['Quantity'].sum()
    # Convert to plain Python types (int if possible)
    result = {region: int(qty) if pd.notna(qty) else 0 for region, qty in result_series.items()}
    return result
